  'u.kg': '{v} kg', 'u.tesla': '{v} T', 'u.density': '{v} g/cm³', 'u.mg': '{v} mg', 'u.gw': '{v} GW', 'u.num': '{v}', 'u.yr': '{v} years', 'u.neverDouble': 'never doubles', 'u.months': '{v} months', 'u.mwm2': '{v} MW/m²', 'u.noDemo': 'none',
  'rx.dt': 'D–T', 'rx.dd': 'D–D', 'rx.dhe3': 'D–³He', 'rx.pb11': 'p–¹¹B',
